public class DeferredRunner {interface Task{Object run();}static void run(String name,int mode,Task t){DeferredSupport.trace=0;DeferredSupport.mode=mode;DeferredSupport.field=5;DeferredSupport.shared=new int[]{7};try{System.out.println(name+mode+":"+t.run()+":"+DeferredSupport.trace);}catch(RuntimeException e){System.out.println(name+mode+":"+e.getClass().getName()+":"+(e==DeferredSupport.FAILURE)+":"+DeferredSupport.trace);}}public static void main(String[]a){for(int m=0;m<3;m++){run("callAdd",m,()->DeferredComposite.callAdd());run("callNeg",m,()->DeferredComposite.callNeg());run("fieldAdd",m,()->DeferredComposite.fieldAdd());run("div",m,()->DeferredComposite.divAdd(10,2));run("divZero",m,()->DeferredComposite.divAdd(10,0));}}}
